target.css:
:root {
  --ink: #18263d;
  --paper: #fffdf7;
  --blue: #2866d8;
  --mint: #d8f4e5;
  --line: #bfd0df;
}

.clock-card {
  width: 430px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
}

.card-top,
.card-foot,
.time-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.label {
  margin: 0;
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.live {
  padding: 4px 8px;
  background: var(--mint);
  border-radius: 999px;
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
}

.time-row {
  margin: 16px 0;
  padding: 14px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.opponent {
  color: var(--ink);
  font-size: 14px;
  font-weight: 600;
}

.time {
  color: var(--blue);
  font-size: 28px;
  line-height: 1;
}

.card-foot {
  color: var(--ink);
  font-size: 12px;
  font-weight: 600;
}

button {
  padding: 7px 10px;
  border: 0;
  border-radius: 7px;
  background: var(--blue);
  color: var(--paper);
  font-size: 12px;
  font-weight: 800;
}
